void uHuman::cEnemyClimbInfo::copyCapsule(const MtCapsule* cap) {
    if (cap == nullptr) {
        return;
    }
    mCap.p0.x = cap->p0.x;
    mCap.p0.y = cap->p0.y;
    mCap.p0.z = cap->p0.z;
    mCap.p0.pad_ = 0.0f;
    mCap.p1.x = cap->p1.x;
    mCap.p1.y = cap->p1.y;
    mCap.p1.z = cap->p1.z;
    mCap.p1.pad_ = 0.0f;
    mCap.r = cap->r;
}

void uHuman::cEnemyClimbInfo::copyCapsulefromSphere(const MtSphere* sphere) {
    if (sphere == nullptr) {
        return;
    }
    mCap.p0.x = sphere->pos.x;
    mCap.p0.y = sphere->pos.y;
    mCap.p0.z = sphere->pos.z;
    mCap.p0.pad_ = 0.0f;
    mCap.p1.x = mCap.p0.x;
    mCap.p1.y = mCap.p0.y;
    mCap.p1.z = mCap.p0.z;
    mCap.p1.pad_ = 0.0f;
    mCap.r = sphere->r;
}

