bool uHuman::cLimitActCtrl::isLimited(s32 actID) {
    for (u32 i = 0;;) {
        if (mLimitActList.elems[i].mIsLimited) {
            if (mLimitActList.elems[i].mActID == actID) {
                return true;
            }
        }
        if ((i + 1u) <= 15u) {
            i = i + 1u;
        } else {
            break;
        }
    }
    return false;
}

